def transform(grid):
    """Place the original and its rotations in a 2x2 block arrangement."""
    def rotate_cw(g):
        return [list(row) for row in zip(*g[::-1])]

    def rotate_ccw(g):
        return [list(row) for row in zip(*g)][::-1]

    def rotate_180(g):
        return [row[::-1] for row in g[::-1]]

    tiles = [grid, rotate_cw(grid), rotate_ccw(grid), rotate_180(grid)]
    h = len(grid)
    return [tiles[0][r] + tiles[1][r] for r in range(h)] + [
        tiles[2][r] + tiles[3][r] for r in range(h)
    ]
